/**  High. */
"high" | 
/**  Medium. */
"medium" | 
/**  Low. */
"low" | 
/**  A value from a newer Clauseo that this version does not know. */
"unknown";

/**  The agent's plan, replaced whole (ACP v1 sends the full plan each time). */
